var n=`0849-pani-puri`;var t=`world-0849`;var a=`IN`;var o=`south-asia`;var s=8;var r=72;var l={en:`Pani Puri`,ua:`Пані пурі`};var d={en:`Pani Puri is a India dish made with semolina flour, all-purpose flour, potato, canned chickpeas. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Пані пурі, страва кухні країни Індія. Основні складники: семоліна, пшеничне борошно універсальне, картопля, консервований нут. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 15 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 15 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:15,i:[[`semolina-flour`,240,`g`],[`all-purpose-flour`,60,`g`],[`water`,150,`ml`],[`table-salt`,4,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 15 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 15 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:15,i:[[`canola-oil`,650,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 18 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 18 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:18,i:[[`potato`,260,`g`],[`water`,500,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`canned-chickpeas`,210,`g`],[`tamarind-concentrate`,20,`g`],[`chaat-masala`,7,`g`],[`mint`,25,`g`],[`water`,420,`ml`]]},{en:`Arrange the prepared cooked components and listed toppings in a serving dish, keeping hot foods hot and chilled components cold until serving.`,ua:`Складіть готові приготовлені компоненти й зазначені додатки в посуді для подавання, підтримуючи гаряче гарячим, а холодне охолодженим.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`cilantro`,20,`g`]]}];var g={slug:n,id:t,country:`IN`,region:o,servings:8,minutes:72,title:l,text:d,steps:u};export{a as country,g as default,t as id,r as minutes,o as region,s as servings,n as slug,u as steps,d as text,l as title};